var DATA = {"trigger": "E-stop button pressed", "seq": "Cut drive power|Engage brakes|Hold position|Signal estop", "safe": "Stopped, brakes on, controller alive", "verify": "Brake test before resume"};
console.log("ABORT TRIGGER: " + DATA.trigger);
console.log("Safe state: " + DATA.safe);
var state = "NOMINAL";
DATA.seq.split("|").forEach(function (s, i) {
  s = s.trim();
  state = "ABORT-" + (i + 1);
  console.log("  [" + state + "] " + s);
});
state = "SAFE";
console.log("Reached: " + state + " — " + DATA.safe);
console.log("Verification: " + DATA.verify);
console.log("RESULT: mission aborted to safe state in " + DATA.seq.split("|").length + " steps.");

